import numpy as np
from openai import OpenAI


def embed(texto):
    cliente = OpenAI()
    resp = cliente.embeddings.create(model="mock-embed", input=texto)
    return resp.data[0].embedding


def cosseno(a, b):
    a = np.array(a, dtype=float)
    b = np.array(b, dtype=float)
    na = np.linalg.norm(a)
    nb = np.linalg.norm(b)
    if na == 0.0 or nb == 0.0:
        return 0.0
    return float(np.dot(a, b) / (na * nb))


def topk_prompt(matriz, metadados, pergunta, k):
    q = embed(pergunta)
    scores = [cosseno(linha, q) for linha in matriz]
    ordem = np.argsort(-np.array(scores), kind="stable")
    topk = [int(i) for i in ordem[:k]]
    linhas = [f"[{pos}] {metadados[idx]['texto']}" for pos, idx in enumerate(topk, 1)]
    return "\n".join(linhas) + f"\nPergunta: {pergunta}"


def responder_resiliente(matriz, metadados, pergunta, k, client, max_tentativas):
    prompt = topk_prompt(matriz, metadados, pergunta, k)
    mensagens = [{"role": "user", "content": prompt}]
    for tentativa in range(max_tentativas):
        try:
            if hasattr(client, "chat"):
                resp = client.chat.completions.create(model="mock-4", messages=mensagens)
                return resp.choices[0].message.content
            resp = client.messages.create(model="mock-claude", max_tokens=512, messages=mensagens)
            return resp.content[0].text
        except Exception as e:
            if type(e).__name__ == "RateLimitError" and tentativa < max_tentativas - 1:
                continue
            raise
    raise RuntimeError("esgotou as tentativas")

import json
import re

def parsear_resposta(texto, k):
    m = re.search(r"```(?:json)?\s*(\{.*\})\s*```", texto, re.DOTALL)
    bruto = m.group(1) if m else texto.strip()
    try:
        dados = json.loads(bruto)
    except (json.JSONDecodeError, ValueError):
        return {"resposta": "", "fontes": []}
    if not isinstance(dados, dict):
        return {"resposta": "", "fontes": []}
    fontes = []
    for n in dados.get("fontes", []):
        if isinstance(n, bool):
            continue
        if isinstance(n, int) and 1 <= n <= k:
            fontes.append(n)
    return {"resposta": dados.get("resposta", ""), "fontes": fontes}
